CREATE OR REPLACE FUNCTION public.queue_approval_batch(p_batch_id uuid, p_actor uuid, p_jobs jsonb, p_request_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event uuid;
  v_job jsonb;
  v_app public.applications%rowtype;
  v_committee public.committees%rowtype;
  v_new uuid;
  v_job_id uuid;
  v_existing public.mail_batches%rowtype;
begin
  if jsonb_typeof(p_jobs) <> 'array' or jsonb_array_length(p_jobs) not between 1 and 500
    or p_request_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'INVALID_BATCH';
  end if;
  select event_id into v_event from public.staff_members where user_id = p_actor and role = 'admin' and active;
  if v_event is null then raise exception 'FORBIDDEN'; end if;
  insert into public.mail_batches (id, event_id, created_by, request_hash, total)
    values (p_batch_id, v_event, p_actor, p_request_hash, jsonb_array_length(p_jobs))
    on conflict (id) do nothing returning id into v_new;
  if v_new is null then
    select * into v_existing from public.mail_batches where id = p_batch_id for update;
    if v_existing.event_id <> v_event or v_existing.created_by <> p_actor
      or v_existing.request_hash <> p_request_hash then raise exception 'BATCH_CONFLICT'; end if;
    return p_batch_id;
  end if;
  for v_job in select value from jsonb_array_elements(p_jobs) loop
    select * into v_app from public.applications
      where id = (v_job->>'applicationId')::uuid and event_id = v_event for update;
    if not found or v_app.status <> 'pending' or v_app.version <> (v_job->>'version')::integer
      or v_app.email <> (v_job->>'email') then raise exception 'STALE_APPLICATION'; end if;
    select * into v_committee from public.committees
      where id = (v_job->>'committeeId')::uuid and event_id = v_event and active;
    if not found then raise exception 'INVALID_COMMITTEE'; end if;
    v_job_id := gen_random_uuid();
    insert into public.mail_jobs (
      id, batch_id, application_id, approval_version, recipient_email, recipient_name,
      committee_name, subject, html_content, text_content, tag
    ) values (
      v_job_id, p_batch_id, v_app.id, v_app.version + 1, v_app.email,
      v_app.first_name || ' ' || v_app.last_name, v_committee.name,
      v_job->>'subject', v_job->>'html', v_job->>'text', 'aero-job-' || v_job_id::text
    );
    update public.applications set status = 'approval_queued', committee_id = v_committee.id,
      version = version + 1, updated_at = now() where id = v_app.id;
  end loop;
  insert into public.audit_logs(actor_id, action, target_id, summary)
    values (p_actor, 'batch_created', p_batch_id, jsonb_build_object('count', jsonb_array_length(p_jobs)));
  return p_batch_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_mail_event(p_fingerprint text, p_tag text, p_message_id text, p_email text, p_event text, p_provider_time timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.mail_jobs%rowtype;
  v_app public.applications%rowtype;
  v_raw text;
  v_code text;
begin
  select * into v_job from public.mail_jobs where tag = p_tag for update;
  if not found or v_job.recipient_email <> lower(btrim(p_email))
    or (v_job.provider_message_id is not null and
      lower(btrim(btrim(v_job.provider_message_id), '<>')) <>
      lower(btrim(btrim(p_message_id), '<>'))) then
    return false;
  end if;
  insert into public.mail_events(fingerprint, job_id, message_id, recipient_email, event_name, provider_time)
    values (p_fingerprint, v_job.id, p_message_id, lower(btrim(p_email)), p_event, p_provider_time)
    on conflict (fingerprint) do nothing;
  if not found then return true; end if;
  update public.mail_jobs set provider_message_id = coalesce(provider_message_id, p_message_id),
    delivery_status = case when p_provider_time is not null and
      (last_delivery_event_at is null or p_provider_time >= last_delivery_event_at) then case p_event
      when 'delivered' then 'delivered' when 'deferred' then 'deferred'
      when 'hard_bounce' then 'hard_bounced' when 'soft_bounce' then 'soft_bounced'
      when 'blocked' then 'blocked' when 'invalid_email' then 'invalid'
      when 'spam' then 'complained' when 'error' then 'error'
      when 'unsubscribed' then 'unsubscribed' else delivery_status end else delivery_status end,
    last_delivery_event_at = case when p_event in ('delivered', 'deferred', 'hard_bounce',
      'soft_bounce', 'blocked', 'invalid_email', 'spam', 'error', 'unsubscribed') and
      p_provider_time is not null and (last_delivery_event_at is null or p_provider_time >= last_delivery_event_at)
      then p_provider_time else last_delivery_event_at end,
    status = case when p_event in ('request', 'delivered') then 'sent'
      when p_event = 'invalid_email' and status <> 'sent' then 'failed'
      else status end,
    updated_at = now() where id = v_job.id;
  if p_event in ('request', 'delivered') then
    select * into v_app from public.applications where id = v_job.application_id for update;
    if v_app.status = 'approval_queued' and v_app.version = v_job.approval_version then
      update public.applications set status = 'approved', approved_at = now(), updated_at = now()
        where id = v_app.id;
      v_raw := 'AERO1:' || rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');
      v_code := upper(substr(encode(extensions.gen_random_bytes(8), 'hex'), 1, 10));
      insert into public.qr_credentials(application_id, raw_value, value_hash, manual_code)
        values (v_app.id, v_raw, encode(extensions.digest(v_raw, 'sha256'), 'hex'), v_code)
        on conflict (application_id) do nothing;
    end if;
  end if;
  update public.mail_events set processed = true where fingerprint = p_fingerprint;
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_in_code(p_code text, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_event public.events%rowtype;
  v_app public.applications%rowtype;
  v_existing public.check_ins%rowtype;
  v_committee_name text;
  v_qr_active boolean;
  v_attempts integer;
  v_inserted uuid;
begin
  select e.* into v_event from public.events e join public.staff_members s on s.event_id = e.id
    where s.user_id = v_actor and s.active limit 1;
  if not found then raise exception 'FORBIDDEN'; end if;
  insert into public.check_in_attempts(user_id, minute, attempts)
    values (v_actor, date_trunc('minute', now()), 1)
    on conflict (user_id, minute) do update set attempts = public.check_in_attempts.attempts + 1
    returning attempts into v_attempts;
  if v_attempts > 60 then raise exception 'RATE_LIMIT'; end if;
  if not v_event.check_in_open then return jsonb_build_object('result', 'closed'); end if;
  if length(p_code) > 80 then return jsonb_build_object('result', 'invalid'); end if;
  select a.* into v_app from public.applications a
    join public.qr_credentials q on q.application_id = a.id
    where a.event_id = v_event.id and
      (q.value_hash = encode(extensions.digest(p_code, 'sha256'), 'hex') or q.manual_code = upper(p_code))
    for update of a;
  if not found then return jsonb_build_object('result', 'invalid'); end if;
  select active into v_qr_active from public.qr_credentials where application_id = v_app.id;
  if v_app.status <> 'approved' or not v_qr_active then return jsonb_build_object('result', 'inactive'); end if;
  select name into v_committee_name from public.committees where id = v_app.committee_id;
  select * into v_existing from public.check_ins where event_id = v_event.id and application_id = v_app.id;
  if found then
    return jsonb_build_object('result', case when v_existing.request_id = p_request_id then 'recorded' else 'already' end,
      'firstName', v_app.first_name, 'lastName', v_app.last_name,
      'committee', v_committee_name, 'checkedInAt', v_existing.checked_in_at);
  end if;
  insert into public.check_ins(event_id, application_id, staff_user_id, request_id)
    values (v_event.id, v_app.id, v_actor, p_request_id)
    on conflict (event_id, application_id) do nothing returning id into v_inserted;
  if v_inserted is null then
    select * into v_existing from public.check_ins where event_id = v_event.id and application_id = v_app.id;
    return jsonb_build_object('result', case when v_existing.request_id = p_request_id then 'recorded' else 'already' end,
      'firstName', v_app.first_name, 'lastName', v_app.last_name,
      'committee', v_committee_name, 'checkedInAt', v_existing.checked_in_at);
  end if;
  insert into public.audit_logs(actor_id, action, target_id) values (v_actor, 'check_in', v_app.id);
  return jsonb_build_object('result', 'recorded', 'firstName', v_app.first_name,
    'lastName', v_app.last_name, 'committee', v_committee_name, 'checkedInAt', now());
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_mail_jobs(p_worker uuid, p_limit integer DEFAULT 20)
 RETURNS SETOF mail_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_state public.mail_provider_state%rowtype;
  v_date date := (now() at time zone 'Europe/Istanbul')::date;
  v_slots integer;
  v_id uuid;
  v_count integer := 0;
begin
  update public.mail_jobs set status = 'uncertain', lease_owner = null, lease_until = null,
    last_error = 'İşleyici yanıtı kayboldu; sağlayıcı olayı araştırılmalı.', updated_at = now()
    where status = 'sending' and lease_until < now();
  select * into v_state from public.mail_provider_state where id = 1 for update;
  if v_state.sent_day is distinct from v_date then
    update public.mail_provider_state set sent_day = v_date, reserved_today = 0 where id = 1;
    v_state.reserved_today := 0;
  end if;
  v_slots := greatest(0, v_state.approval_budget - v_state.reserved_today);
  if v_state.send_blocked_until is not null and v_state.send_blocked_until > now() then
    v_slots := 0;
  end if;
  if v_state.provider_remaining is not null then
    v_slots := least(v_slots, greatest(0, v_state.provider_remaining - v_state.auth_reserve));
  end if;
  v_slots := least(v_slots, greatest(0, least(p_limit, 20)));
  for v_id in
    select id from public.mail_jobs
      where status in ('queued', 'quota_wait') and next_attempt_at <= now()
      order by created_at for update skip locked limit v_slots
  loop
    update public.mail_jobs set status = 'sending', lease_owner = p_worker,
      lease_until = now() + interval '2 minutes', first_send_at = coalesce(first_send_at, now()),
      reservation_day = v_date, attempts = attempts + 1, updated_at = now() where id = v_id;
    v_count := v_count + 1;
    return query select * from public.mail_jobs where id = v_id;
  end loop;
  update public.mail_provider_state set reserved_today = reserved_today + v_count,
    provider_remaining = case when provider_remaining is null then null else greatest(0, provider_remaining - v_count) end,
    worker_heartbeat_at = now() where id = 1;
  if v_slots = 0 then
    update public.mail_jobs set status = 'quota_wait', updated_at = now()
      where status = 'queued' and next_attempt_at <= now();
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_mail_job(p_job_id uuid, p_worker uuid, p_status mail_job_status, p_message_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_next_attempt timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_updated uuid;
  v_reservation_day date;
begin
  if p_status not in ('provider_accepted', 'uncertain', 'quota_wait', 'queued', 'failed') then
    raise exception 'INVALID_STATUS';
  end if;
  update public.mail_jobs set status = p_status, provider_message_id = coalesce(p_message_id, provider_message_id),
    last_error = left(p_error, 500), next_attempt_at = coalesce(p_next_attempt, next_attempt_at),
    lease_owner = null, lease_until = null, updated_at = now()
    where id = p_job_id and status = 'sending' and lease_owner = p_worker and lease_until > now()
    returning id, reservation_day into v_updated, v_reservation_day;
  if v_updated is not null and p_status in ('quota_wait', 'queued', 'failed') then
    update public.mail_provider_state set
      reserved_today = case when sent_day = v_reservation_day then greatest(0, reserved_today - 1)
        else reserved_today end,
      send_blocked_until = case when p_status in ('quota_wait', 'queued') and p_next_attempt is not null
        then greatest(coalesce(send_blocked_until, p_next_attempt), p_next_attempt)
        else send_blocked_until end where id = 1;
  end if;
  return v_updated is not null;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_application(p_application_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_event uuid;
  v_application public.applications%rowtype;
begin
  select event_id into v_event from public.staff_members where user_id = v_actor and role = 'admin' and active;
  if v_event is null then raise exception 'FORBIDDEN'; end if;
  select * into v_application from public.applications
    where id = p_application_id and event_id = v_event for update;
  if not found then return false; end if;
  update public.applications set status = 'cancelled', version = version + 1,
    updated_at = now() where id = v_application.id;
  update public.qr_credentials set active = false where application_id = v_application.id;
  update public.mail_jobs set status = 'cancelled', updated_at = now()
    where application_id = v_application.id and status in ('queued', 'quota_wait', 'failed');
  insert into public.audit_logs(actor_id, action, target_id) values (v_actor, 'application_cancelled', p_application_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.rotate_qr(p_application_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_event uuid;
  v_application public.applications%rowtype;
  v_raw text;
  v_code text;
begin
  select event_id into v_event from public.staff_members where user_id = v_actor and role = 'admin' and active;
  if v_event is null then raise exception 'FORBIDDEN'; end if;
  select * into v_application from public.applications
    where id = p_application_id and event_id = v_event for update;
  if not found or v_application.status <> 'approved' then return false; end if;
  v_raw := 'AERO1:' || rtrim(translate(encode(extensions.gen_random_bytes(32), 'base64'), '+/', '-_'), '=');
  v_code := upper(substr(encode(extensions.gen_random_bytes(8), 'hex'), 1, 10));
  update public.qr_credentials set raw_value = v_raw,
    value_hash = encode(extensions.digest(v_raw, 'sha256'), 'hex'), manual_code = v_code,
    active = true, version = version + 1, created_at = now()
    where application_id = v_application.id;
  if not found then return false; end if;
  insert into public.audit_logs(actor_id, action, target_id) values (v_actor, 'qr_rotated', p_application_id);
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_failed_approval(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_job public.mail_jobs%rowtype;
  v_app public.applications%rowtype;
begin
  select * into v_job from public.mail_jobs where id = p_job_id for update;
  if not found or v_job.status <> 'failed' or v_job.reopened_at is not null then return false; end if;
  select * into v_app from public.applications where id = v_job.application_id for update;
  if not found or v_app.status <> 'approval_queued'
    or v_app.version <> v_job.approval_version then return false; end if;
  if not exists (
    select 1 from public.staff_members
    where user_id = v_actor and event_id = v_app.event_id and role = 'admin' and active
  ) then raise exception 'FORBIDDEN'; end if;
  update public.applications set status = 'pending', committee_id = null,
    version = version + 1, updated_at = now() where id = v_app.id;
  update public.mail_jobs set reopened_at = now(), updated_at = now() where id = p_job_id;
  insert into public.audit_logs(actor_id, action, target_id, summary)
    values (v_actor, 'failed_approval_reopened', v_app.id, jsonb_build_object('job_id', p_job_id));
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION private.check_admin_login_rate_limit(p_ip inet, p_device_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(allowed boolean, wait_seconds integer, failure_count integer, suspicious boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare r public.admin_login_rate_limits%rowtype;
begin
  select * into r from public.admin_login_rate_limits
  where coalesce(ip_address::text, '') = coalesce(p_ip::text, '') and coalesce(device_id::text, '') = coalesce(p_device_id::text, '')
  for update;
  if not found then return query select true, 0, 0, false; return; end if;
  if r.blocked_until is not null and r.blocked_until > p_now then
    return query select false, greatest(1, ceil(extract(epoch from (r.blocked_until - p_now)))::integer), r.failure_count, true;
  end if;
  return query select true, 0, r.failure_count, r.suspicious;
end $function$

CREATE OR REPLACE FUNCTION private.record_admin_login_failure(p_ip inet, p_device_id uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS TABLE(allowed boolean, wait_seconds integer, failure_count integer, suspicious boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
declare r public.admin_login_rate_limits%rowtype; n integer; delay_seconds integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(private.login_rate_limit_key(p_ip, p_device_id), 0));
  select * into r from public.admin_login_rate_limits
  where coalesce(ip_address::text, '') = coalesce(p_ip::text, '') and coalesce(device_id::text, '') = coalesce(p_device_id::text, '')
  for update;
  if found and r.blocked_until is not null and r.blocked_until > p_now then
    return query select false, greatest(1, ceil(extract(epoch from (r.blocked_until - p_now)))::integer), r.failure_count, true; return;
  end if;
  n := coalesce(r.failure_count, 0) + 1;
  delay_seconds := case when n >= 5 then 900 else power(2, n - 1)::integer end;
  insert into public.admin_login_rate_limits(ip_address, device_id, failure_count, last_failure_at, blocked_until, suspicious, updated_at)
  values (p_ip, p_device_id, n, p_now, case when n >= 5 then p_now + make_interval(secs => delay_seconds) else null end, n >= 4, p_now)
  on conflict ((coalesce(ip_address::text, '')), (coalesce(device_id::text, ''))) do update set
    failure_count = excluded.failure_count, last_failure_at = excluded.last_failure_at, blocked_until = excluded.blocked_until,
    suspicious = excluded.suspicious, updated_at = excluded.updated_at
  returning * into r;
  return query select true, delay_seconds, r.failure_count, r.suspicious;
end $function$

CREATE OR REPLACE FUNCTION public.claim_batch_mail_jobs(p_worker uuid, p_batch_id uuid, p_limit integer)
 RETURNS SETOF mail_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_state public.mail_provider_state%rowtype; v_date date:=(now() at time zone 'Europe/Istanbul')::date;
 v_slots integer; v_id uuid; v_count integer:=0;
begin
 if p_batch_id is null or p_worker is null or p_limit is null or p_limit not between 1 and 20
 then raise exception 'INVALID_CLAIM'; end if;
 update public.mail_jobs set status='uncertain',lease_owner=null,lease_until=null,
 last_error='İşleyici yanıtı kayboldu; sağlayıcı olayı araştırılmalı.',updated_at=now()
 where status='sending' and lease_until<now();
 select * into v_state from public.mail_provider_state where id=1 for update;
 if v_state.sent_day is distinct from v_date then
  update public.mail_provider_state set sent_day=v_date,reserved_today=0 where id=1;
  v_state.reserved_today:=0;
 end if;
 v_slots:=greatest(0,v_state.approval_budget-v_state.reserved_today);
 if v_state.send_blocked_until is not null and v_state.send_blocked_until>now() then v_slots:=0; end if;
 if v_state.provider_remaining is not null then
  v_slots:=least(v_slots,greatest(0,v_state.provider_remaining-v_state.auth_reserve));
 end if;
 v_slots:=least(v_slots,p_limit);
 for v_id in select id from public.mail_jobs where batch_id=p_batch_id
  and status in('queued','quota_wait') and next_attempt_at<=now()
  order by created_at,id for update skip locked limit v_slots
 loop
  update public.mail_jobs set status='sending',lease_owner=p_worker,lease_until=now()+interval '2 minutes',
   first_send_at=coalesce(first_send_at,now()),reservation_day=v_date,attempts=attempts+1,updated_at=now() where id=v_id;
  v_count:=v_count+1;
  return query select * from public.mail_jobs where id=v_id;
 end loop;
 update public.mail_provider_state set reserved_today=reserved_today+v_count,
  provider_remaining=case when provider_remaining is null then null else greatest(0,provider_remaining-v_count) end,
  worker_heartbeat_at=now() where id=1;
 if v_slots=0 then
  update public.mail_jobs set status='quota_wait',updated_at=now()
   where batch_id=p_batch_id and status='queued' and next_attempt_at<=now();
 end if;
end; $function$
